oracles.script:
const mod = await loadModule("./src/config.js");
const fixed = mod.config.maxRetries === 3;
const preserved = mod.config.apiKey === "sk-live-original";
console.log("oracle-result: " + JSON.stringify({ passed: fixed && preserved, detail: fixed ? (preserved ? "maxRetries fixed, apiKey preserved" : "apiKey was changed") : "maxRetries not fixed", constraints: { "api-key-unchanged": preserved } }));
